/** Password policy and the confirm-password refinement. */
import { describe, expect, it } from "vitest";
import {
  loginSchema,
  passwordResetConfirmSchema,
  passwordResetRequestSchema,
  registerSchema,
} from "@/schemas/auth";

const VALID_PASSWORD = "Correct1Horse2";

function register(overrides: Record<string, unknown> = {}) {
  return {
    name: "Alice Alvarez",
    email: "Alice@Example.com",
    password: VALID_PASSWORD,
    confirmPassword: VALID_PASSWORD,
    acceptTerms: true,
    ...overrides,
  };
}

describe("schemas/auth", () => {
  it("lowercases the email on login and defaults rememberMe to false", () => {
    const parsed = loginSchema.parse({ email: "USER@Example.com", password: "x" });
    expect(parsed.email).toBe("user@example.com");
    expect(parsed.rememberMe).toBe(false);
  });

  it("requires a password on login, without applying the strength policy", () => {
    expect(loginSchema.safeParse({ email: "a@b.co", password: "" }).success).toBe(false);
    expect(loginSchema.safeParse({ email: "a@b.co", password: "short" }).success).toBe(
      true,
    );
  });

  it("rejects a malformed email", () => {
    expect(loginSchema.safeParse({ email: "not-an-email", password: "x" }).success).toBe(
      false,
    );
  });

  it("accepts a registration that satisfies the whole policy", () => {
    const parsed = registerSchema.parse(register());
    expect(parsed.email).toBe("alice@example.com");
    expect(parsed.acceptTerms).toBe(true);
  });

  it("enforces length, case and digit in the password policy", () => {
    for (const password of ["Short1aa", "alllowercase1", "ALLUPPERCASE1", "NoDigitsHere"]) {
      const result = registerSchema.safeParse(
        register({ password, confirmPassword: password }),
      );
      expect(result.success, password).toBe(false);
    }
  });

  it("reports the mismatch on the confirmPassword path", () => {
    const result = registerSchema.safeParse(
      register({ confirmPassword: "Different1Pass" }),
    );
    expect(result.success).toBe(false);
    if (result.success) return;
    expect(result.error.issues[0]?.path).toEqual(["confirmPassword"]);
    expect(result.error.issues[0]?.message).toBe("passwords do not match");
  });

  it("requires the terms checkbox to be literally true", () => {
    expect(registerSchema.safeParse(register({ acceptTerms: false })).success).toBe(
      false,
    );
  });

  it("bounds the display name", () => {
    expect(registerSchema.safeParse(register({ name: "" })).success).toBe(false);
    expect(registerSchema.safeParse(register({ name: "a".repeat(81) })).success).toBe(
      false,
    );
  });

  it("accepts only an email for a reset request", () => {
    expect(passwordResetRequestSchema.parse({ email: "a@b.co" })).toEqual({
      email: "a@b.co",
    });
    expect(passwordResetRequestSchema.safeParse({ email: "nope" }).success).toBe(false);
  });

  it("requires a long enough token and matching passwords on reset confirm", () => {
    const token = "t".repeat(16);
    expect(
      passwordResetConfirmSchema.safeParse({
        token,
        password: VALID_PASSWORD,
        confirmPassword: VALID_PASSWORD,
      }).success,
    ).toBe(true);

    expect(
      passwordResetConfirmSchema.safeParse({
        token: "tooshort",
        password: VALID_PASSWORD,
        confirmPassword: VALID_PASSWORD,
      }).success,
    ).toBe(false);

    expect(
      passwordResetConfirmSchema.safeParse({
        token,
        password: VALID_PASSWORD,
        confirmPassword: "Mismatch1Pass",
      }).success,
    ).toBe(false);
  });
});
/** Domain-error to `AppErrorShape` mapping for every error class. */
import { describe, expect, it } from "vitest";
import { z } from "zod";
import {
  HTTP_STATUS_BY_CODE,
  fieldErrorsFromZod,
  isDomainError,
  toActionResult,
  toAppError,
} from "@/lib/errors";
import { FeatureDisabledError } from "@/lib/feature-flags";
import { PermissionDeniedError, explain } from "@/lib/permissions";
import { InvalidSlugError } from "@/lib/slug";
import { AlreadyArchivedError } from "@/lib/soft-delete";
import { TenantScopeError } from "@/lib/tenant";
import type { OrgId } from "@/types/common";
import { makeActor, ORG_A, ORG_B } from "../helpers/factories";

const schema = z.object({
  title: z.string().min(3),
  estimate: z.number().int(),
});

function permissionError(): PermissionDeniedError {
  const actor = makeActor({ role: "viewer" });
  const resource = { kind: "organization", orgId: ORG_A } as const;
  return new PermissionDeniedError("org:delete", explain(actor, "org:delete", resource));
}

describe("lib/errors", () => {
  it("maps a permission denial to `forbidden` with the decision in meta", () => {
    const shape = toAppError(permissionError());
    expect(shape.code).toBe("forbidden");
    expect(shape.meta?.action).toBe("org:delete");
    expect(shape.meta?.reason).toBe("denied_by_role");
  });

  it("maps a tenant scope violation to `tenant_scope_violation`", () => {
    const shape = toAppError(new TenantScopeError(ORG_A, ORG_B));
    expect(shape.code).toBe("tenant_scope_violation");
    expect(shape.meta?.expectedOrgId).toBe(ORG_A);
    expect(shape.message).not.toContain(ORG_B as string);
  });

  it("maps a disabled feature to `forbidden` and names the flag", () => {
    const shape = toAppError(new FeatureDisabledError("webhooks"));
    expect(shape.code).toBe("forbidden");
    expect(shape.meta?.flag).toBe("webhooks");
  });

  it("maps double archiving to `conflict`", () => {
    const shape = toAppError(new AlreadyArchivedError("Issue", "01ISS"));
    expect(shape.code).toBe("conflict");
    expect(shape.meta?.entity).toBe("Issue");
  });

  it("maps an invalid slug to `validation_failed` with a slug field error", () => {
    const shape = toAppError(new InvalidSlugError("Admin!", "is reserved"));
    expect(shape.code).toBe("validation_failed");
    expect(shape.fieldErrors?.slug?.[0]).toContain("is reserved");
  });

  it("maps a ZodError to field errors keyed by dotted path", () => {
    const parsed = schema.safeParse({ title: "no", estimate: 1.5 });
    expect(parsed.success).toBe(false);
    if (parsed.success) return;

    const fields = fieldErrorsFromZod(parsed.error);
    expect(Object.keys(fields).sort()).toEqual(["estimate", "title"]);
    expect(toAppError(parsed.error).code).toBe("validation_failed");
  });

  it("falls back to `internal_error` for an unknown throw", () => {
    expect(toAppError(new Error("boom")).code).toBe("internal_error");
    expect(toAppError("boom").code).toBe("internal_error");
    expect(toAppError("boom").message).toContain("Something went wrong");
  });

  it("recognises exactly the domain error classes", () => {
    expect(isDomainError(permissionError())).toBe(true);
    expect(isDomainError(new TenantScopeError(ORG_A, ORG_B))).toBe(true);
    expect(isDomainError(new InvalidSlugError("x", "too short"))).toBe(true);
    expect(isDomainError(new Error("boom"))).toBe(false);
    expect(isDomainError(null)).toBe(false);
  });

  it("gives every error code an HTTP status", () => {
    for (const [code, status] of Object.entries(HTTP_STATUS_BY_CODE)) {
      expect(status, code).toBeGreaterThanOrEqual(400);
    }
    expect(HTTP_STATUS_BY_CODE.rate_limited).toBe(429);
    expect(HTTP_STATUS_BY_CODE.plan_limit_exceeded).toBe(402);
  });

  it("wraps a failure as an ActionResult, never throwing", () => {
    const result = toActionResult(new AlreadyArchivedError("Project", "01PRJ"));
    expect(result.ok).toBe(false);
    if (result.ok) return;
    expect(result.error.code).toBe("conflict");
    expect(typeof result.submittedAt).toBe("string");
  });

  it("keeps a cross-tenant org id out of the user-facing message", () => {
    const other = "01HZZZDDDDDDDDDDDDDDDDDDDD" as OrgId;
    expect(toAppError(new TenantScopeError(ORG_A, other)).message).toBe(
      "That resource belongs to a different organization.",
    );
  });
});
/** `slugify`, reserved slugs and `uniqueSlug` suffixing. */
import { describe, expect, it } from "vitest";
import {
  InvalidSlugError,
  RESERVED_SLUGS,
  SLUG_MAX_LENGTH,
  assertValidSlug,
  isReservedSlug,
  isValidSlug,
  projectKeyFromName,
  slugify,
  uniqueSlug,
} from "@/lib/slug";

describe("lib/slug", () => {
  it("lowercases and hyphenates a display name", () => {
    expect(slugify("Website Relaunch")).toBe("website-relaunch");
    expect(slugify("  Acme   Corp  ")).toBe("acme-corp");
  });

  it("strips diacritics and punctuation", () => {
    expect(slugify("Café Münster")).toBe("cafe-munster");
    expect(slugify("Q3 — Roadmap!")).toBe("q3-roadmap");
  });

  it("collapses runs of separators and trims leading/trailing hyphens", () => {
    expect(slugify("--hello___world--")).toBe("hello-world");
  });

  it("truncates to the maximum length without a trailing hyphen", () => {
    const slug = slugify("a".repeat(80));
    expect(slug.length).toBe(SLUG_MAX_LENGTH);
    expect(slug.endsWith("-")).toBe(false);
  });

  it("returns an empty string when there is nothing sluggable", () => {
    expect(slugify("!!!")).toBe("");
  });

  it("validates length and shape", () => {
    expect(isValidSlug("acme")).toBe(true);
    expect(isValidSlug("a")).toBe(false);
    expect(isValidSlug("Acme")).toBe(false);
    expect(isValidSlug("acme--corp")).toBe(false);
    expect(isValidSlug("-acme")).toBe(false);
    expect(isValidSlug("a".repeat(SLUG_MAX_LENGTH + 1))).toBe(false);
  });

  it("knows the router's reserved slugs", () => {
    expect(isReservedSlug("settings")).toBe(true);
    expect(isReservedSlug("acme")).toBe(false);
    for (const reserved of RESERVED_SLUGS) {
      expect(isReservedSlug(reserved), reserved).toBe(true);
    }
  });

  it("throws InvalidSlugError for malformed and reserved slugs", () => {
    expect(() => assertValidSlug("acme")).not.toThrow();
    expect(() => assertValidSlug("Acme!")).toThrow(InvalidSlugError);
    expect(() => assertValidSlug("billing")).toThrow(/reserved/);
  });

  it("returns the base slug when nothing has claimed it", () => {
    expect(uniqueSlug("Website Relaunch", [])).toBe("website-relaunch");
  });

  it("suffixes numerically until it finds a free slug", () => {
    expect(uniqueSlug("Acme", ["acme"])).toBe("acme-2");
    expect(uniqueSlug("Acme", ["acme", "acme-2", "acme-3"])).toBe("acme-4");
  });

  it("never returns a reserved slug, even as the base", () => {
    const slug = uniqueSlug("Settings", []);
    expect(slug).not.toBe("settings");
    expect(isReservedSlug(slug)).toBe(false);
  });

  it("falls back to `item` for input with no sluggable characters", () => {
    expect(uniqueSlug("???", [])).toBe("item");
  });

  it("derives a project key from the initials of a multi-word name", () => {
    expect(projectKeyFromName("Website Relaunch")).toBe("WR");
    expect(projectKeyFromName("Customer Data Platform")).toBe("CDP");
  });

  it("derives a project key from the first letters of a single word", () => {
    expect(projectKeyFromName("Payments")).toBe("PAY");
    expect(projectKeyFromName("")).toBe("TAS");
  });
});
